{"path":"assets/css/styles.css","content":":root{
  --bg:#fbfdfb;
  --muted:#5b6b62;
  --accent:#7cc39b;
  --dark:#123225;
  --card:#ffffff;
  --radius:12px;
  --gap:24px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:var(--dark);background:var(--bg)}
.container{max-width:1000px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:saturate(1) blur(4px);position:sticky;top:0;z-index:40;border-bottom:1px solid rgba(18,50,37,0.04)}
.header-inner{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--dark);text-decoration:none}
.primary-nav a{margin:0 8px;color:var(--muted);text-decoration:none}
.nav-actions .btn{margin-left:12px}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;border:1px solid transparent;background:transparent;color:var(--dark);text-decoration:none;cursor:pointer}
.btn-primary{background:var(--accent);color:#05321a;border-color:rgba(0,0,0,0.04)}
.btn-strong{background:#123225;color:#fff}
.btn-ghost{border-color:rgba(18,50,37,0.08)}
.hero{padding:48px 0;background-image:url('/assets/img/pattern.svg');background-repeat:repeat;}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:32px;align-items:center}
.hero-copy h1{font-size:clamp(1.6rem,2.6vw,2.4rem);margin:0 0 12px}
.lead{color:var(--muted);max-width:64ch}
.hero-visual svg{width:100%;height:auto;border-radius:12px}
.micro-habits,.diagnostic,.plan,.pricing,.final-cta{padding:48px 0}
.habit-list{display:flex;gap:18px;list-style:none;padding:0;margin:18px 0 0}
.habit-list li{background:var(--card);padding:16px;border-radius:10px;flex:1;box-shadow:0 6px 18px rgba(18,50,37,0.04)}
.muted{color:var(--muted)}
.diagnostic-form, .planner-form{display:grid;grid-template-columns:1fr 1fr;gap:12px;background:var(--card);padding:16px;border-radius:12px;box-shadow:0 8px 20px rgba(18,50,37,0.03)}
.diagnostic-form label, .planner-form label{display:flex;flex-direction:column;font-size:0.95rem}
.diagnostic-form select, .planner-form input, .planner-form select, .planner-form textarea{padding:8px;border-radius:8px;border:1px solid rgba(18,50,37,0.08);margin-top:8px}
#to-planner{grid-column:1 / -1;justify-self:start}
.planner-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}
.planner-output{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 8px 20px rgba(18,50,37,0.03)}
#plan-summary{width:100%;border-radius:8px;border:1px solid rgba(18,50,37,0.06);padding:12px;font-family:monospace;background:#fbfdfb}
.output-actions{display:flex;gap:8px;margin-top:8px}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.tier{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(18,50,37,0.04);text-align:center}
.tier.featured{transform:translateY(-8px);border:2px solid rgba(124,195,155,0.15)}
.tier .price{font-size:1.6rem;margin:8px 0}
.site-footer{background:#fff;padding:28px 0;border-top:1px solid rgba(18,50,37,0.04);margin-top:32px}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.attribution{text-align:center;color:var(--muted);padding:12px}

/* Reveal animations */
.reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.8,.2,1),transform 520ms cubic-bezier(.2,.8,.2,1)}
.reveal.is-visible{opacity:1;transform:none}

/* Responsive */
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .planner-grid{grid-template-columns:1fr}
  .diagnostic-form, .planner-form{grid-template-columns:1fr}
  .pricing-grid{grid-template-columns:1fr}
  .primary-nav{display:none}
}

/* Reduced motion */
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Scroll-triggered reveal with respects to prefers-reduced-motion
  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const revealElements = document.querySelectorAll('.reveal');

  if(prefersReduced){
    revealElements.forEach(el=>el.classList.add('is-visible'));
  } else if('IntersectionObserver' in window){
    const io = new IntersectionObserver((entries, obs)=>{
      entries.forEach(entry=>{
        if(entry.isIntersecting){
          entry.target.classList.add('is-visible');
          obs.unobserve(entry.target);
        }
      });
    },{threshold:0.12});
    revealElements.forEach(el=>io.observe(el));
  } else {
    // fallback
    revealElements.forEach(el=>el.classList.add('is-visible'));
  }

  // Quick check -> planner transfer
  const toPlannerBtn = document.getElementById('to-planner');
  if(toPlannerBtn){
    toPlannerBtn.addEventListener('click',()=>{
      const focus = document.getElementById('focus').value;
      const time = document.getElementById('time').value;
      // seed planner fields with suggested defaults
      const title = document.getElementById('sp-title');
      const outcome = document.getElementById('sp-outcome');
      const duration = document.getElementById('sp-duration');
      const habit = document.getElementById('sp-habit');

      const focusMap = {
        energy: 'Stabilize my energy swings',
        clarity: 'Create clearer focus blocks',
        sleep: 'Ease into a calmer evening routine',
        boundaries: 'Signal clear work and rest transitions'
      };

      title.value = focusMap[focus] || 'Weekly session';
      outcome.value = focusMap[focus] || '';
      duration.value = time;
      habit.value = (focus==='sleep')? '3-minute wind-down ritual' : (focus==='clarity')? '2-minute priority list' : '2-minute centering breath';

      // smooth-scroll to planner
      document.getElementById('planner').scrollIntoView({behavior:'smooth'});
    });
  }

  // Session Planner logic
  const buildBtn = document.getElementById('build-plan');
  const clearBtn = document.getElementById('clear-plan');
  const copyBtn = document.getElementById('copy-plan');
  const downloadLink = document.getElementById('download-plan');
  const summaryEl = document.getElementById('plan-summary');

  function createSummary(data){
    const lines = [];
    lines.push(`Session: ${data.title}`);
    lines.push(`Primary outcome: ${data.outcome}`);
    lines.push(`Daily commitment: ${data.duration} / day`);
    lines.push(`Weekly frequency: ${data.freq} times`);
    lines.push(`Core habit: ${data.habit}`);
    if(data.constraint) lines.push(`Constraints: ${data.constraint}`);
    lines.push('');
    lines.push('Micro-routine (try this):');
    lines.push(`• Start: 30s settle & breathe`);
    lines.push(`• Practice: ${data.habit} for ${Math.max(3,parseInt(data.duration))} min`);
    lines.push(`• Close: 60s note — what changed?`);
    lines.push('');
    lines.push('Quick checks:');
    lines.push('• Did I start within the first 10 minutes of my chosen window? (Y/N)');
    lines.push('• Did I complete the core habit? (Y/N)');
    lines.push('• One short note:')
    return lines.join('\n');
  }

  if(buildBtn){
    buildBtn.addEventListener('click',()=>{
      const data = {
        title: document.getElementById('sp-title').value.trim() || 'Session',
        outcome: document.getElementById('sp-outcome').value.trim() || 'Outcome',
        duration: document.getElementById('sp-duration').value,
        freq: document.getElementById('sp-freq').value,
        habit: document.getElementById('sp-habit').value.trim() || 'Short habit',
        constraint: document.getElementById('sp-constraint').value.trim()
      };

      const text = createSummary(data);
      summaryEl.value = text;

      // update download link (data URL)
      const blob = new Blob([text],{type:'text/plain;charset=utf-8'});
      const url = URL.createObjectURL(blob);
      downloadLink.href = url;

      // focus summary for keyboard users
      summaryEl.focus();
    });
  }

  if(clearBtn){
    clearBtn.addEventListener('click',()=>{
      document.getElementById('planner-form').reset();
      summaryEl.value = '';
    });
  }

  if(copyBtn){
    copyBtn.addEventListener('click',async()=>{
      const text = summaryEl.value;
      if(!text) return;
      try{
        if(navigator.clipboard && navigator.clipboard.writeText){
          await navigator.clipboard.writeText(text);
        } else {
          // fallback
          const ta = document.createElement('textarea');
          ta.value = text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();
        }
        copyBtn.textContent = 'Copied ✓';
        setTimeout(()=>copyBtn.textContent = 'Copy text',1600);
      }catch(e){
        console.warn('Copy failed',e);
        copyBtn.textContent = 'Copy failed';
        setTimeout(()=>copyBtn.textContent = 'Copy text',1600);
      }
    });
  }

  // small UX: set current year
  const yearEl = document.getElementById('year');
  if(yearEl) yearEl.textContent = new Date().getFullYear();
});
"} 
